#!/usr/bin/env python3
"""news-image-20261118 entry (variant 3: world map with numbered stories).

Writes the finished 1024x1024 newspaper front page summing up the world's
news of Wednesday 18 November 2026 ("The Daily Globe", world map with
numbered pins and a numbered story list) to /output/entry.png. The image
is embedded below as one base64 line, so the program needs no network and
no other files: it decodes the bytes and writes them unchanged, so two runs
produce byte-identical output.

Run:  MAKEFUN_OUTPUT_DIR=out python3 main.py
"""
import base64
import os

IMAGE_B64 = ""


def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    data = base64.b64decode(IMAGE_B64)
    with open(os.path.join(out_dir, "entry.png"), "wb") as f:
        f.write(data)


if __name__ == "__main__":
    main()
